# DK HCF.  Haderslev - Christiansfeld
#
let hc = path("d3.dk.hcf");

with detail = 4, railway = :first :g1000 :pax :removed {
    # point.dk.Haderslev-Amtsb  dk.VHL

    with link = "line.dk.HCF" {
        track(hc[:had + 349m, :had.ys]);
        track(hc[:had.ys - 0.1dl, :had + 1.51km]);
        line_label(:left:s, hc[:had + 1.5km] << 0.5lt, "HCF");
        track(hc[:had + 1.49km, :ves - 0.49sw]);
    }

    with link = "point.dk.Vesterris", railway = :station {
        track(hc[:ves - 0.5sw, :ves + 0.5sw]);
        marker(:right :de.hp, hc[:ves] >> 0.5lt);
        station(:bottom, hc[:ves] >> 0.5lt >> 1sh + (0.8dt, 0.7dt),
            span(:former, "Westerrüs"),
            "Vesterris",
            "HCF: 3,9"
